-- Frame Library: Top 1/2/3 frames for every rewarded leaderboard family, Hall of Fame, seasonal
-- collections (draft until the Owner releases them), tournament placements and staff role frames.
-- Additive: existing items are never overwritten (ON CONFLICT DO NOTHING), nobody receives anything.

ON CONFLICT (id) DO NOTHING;
--> statement-breakpoint
-- Role frames are never owned: a player may wear one only while holding the matching role (Owner
-- variants also need the matching UID). Used by the equip check and by the trigger below.
CREATE OR REPLACE FUNCTION keyo_role_frame_allowed(p_user uuid, p_frame text) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT CASE p_frame
    WHEN 'role_owner_captain' THEN EXISTS (SELECT 1 FROM user_roles r JOIN users u ON u.id = r.user_id WHERE r.user_id = p_user AND r.role_id = 'owner' AND u.uid = 1000)
    WHEN 'role_owner_gm' THEN EXISTS (SELECT 1 FROM user_roles r JOIN users u ON u.id = r.user_id WHERE r.user_id = p_user AND r.role_id = 'owner' AND u.uid = 1002)
    WHEN 'role_super_admin' THEN EXISTS (SELECT 1 FROM user_roles r WHERE r.user_id = p_user AND r.role_id = 'super_admin')
    WHEN 'role_admin' THEN EXISTS (SELECT 1 FROM user_roles r WHERE r.user_id = p_user AND r.role_id = 'admin')
    WHEN 'role_moderator' THEN EXISTS (SELECT 1 FROM user_roles r WHERE r.user_id = p_user AND r.role_id = 'moderator')
    ELSE false
  END
$$;
--> statement-breakpoint
-- When a role is removed (any path), a role frame that is no longer allowed is taken off at once.
-- Nothing else on the profile changes.
CREATE OR REPLACE FUNCTION keyo_drop_role_frame() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE users SET frame = 'classic'
  WHERE id = OLD.user_id AND frame LIKE 'role\_%' AND NOT keyo_role_frame_allowed(OLD.user_id, frame);
  RETURN OLD;
END;
$$;
--> statement-breakpoint
DROP TRIGGER IF EXISTS user_roles_drop_role_frame ON user_roles;
--> statement-breakpoint
CREATE TRIGGER user_roles_drop_role_frame AFTER DELETE OR UPDATE ON user_roles FOR EACH ROW EXECUTE FUNCTION keyo_drop_role_frame();
--> statement-breakpoint
-- Role frames can never appear in an inventory (so never be listed, gifted or traded).
CREATE OR REPLACE FUNCTION keyo_no_role_items() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM catalog_items c WHERE c.id = NEW.item_id AND c.source = 'role') THEN
    RAISE EXCEPTION 'role_frame: role frames cannot be owned';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
DROP TRIGGER IF EXISTS inventory_items_no_role_items ON inventory_items;
--> statement-breakpoint
CREATE TRIGGER inventory_items_no_role_items BEFORE INSERT OR UPDATE OF item_id ON inventory_items FOR EACH ROW EXECUTE FUNCTION keyo_no_role_items();
